create table if not exists vehicles (id bigint generated by default as identity primary key,name text not null,plate text not null unique,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists expenses (id bigint generated by default as identity primary key,category text not null,amount numeric(12,2) not null check(amount>0),expense_month text not null,vehicle_id bigint references vehicles(id) on delete set null,description text,created_at timestamptz not null default now());
create table if not exists revenues (id bigint generated by default as identity primary key,revenue_date date not null,amount numeric(12,2) not null check(amount>0),customer_name text,description text,created_at timestamptz not null default now());
create table if not exists drivers (id bigint generated by default as identity primary key,name text not null unique,base_salary numeric(12,2) not null default 0,daily_rate numeric(12,2) not null default 0,active boolean not null default true);
create table if not exists driver_trips (id bigint generated by default as identity primary key,driver_name text not null,start_date date not null,end_date date,days_count integer,description text,created_at timestamptz not null default now());
alter table invoices add column if not exists vehicle_id bigint references vehicles(id) on delete set null;
alter table invoices add column if not exists paid_at timestamptz;
create index if not exists expenses_month_idx on expenses(expense_month); create index if not exists invoices_vehicle_idx on invoices(vehicle_id);